<template>
  <div class="leader-list">
    <div class="address-info main-color-bg">
      <p class="desc">您当前所在的位置</p>
      <div class="now-address">
        <div class="address">{{nowAddress}}</div>
        <router-link  to="/address" class="btn">修改地址</router-link>
      </div>
    </div>
    <div class="border-box main-color-bg"><div class="border"></div></div>
    <div class="list-info mescroll" ref="leaderList">
      <div class="wrapper">
        <div class="item" v-for="(item, index) in list" :key="index" @click="selectLeader(item.id)">
          <div class="avatar"><img :src="item.avatar" alt=""></div>
          <div class="info-box">
            <div class="name">
              <span>团长：{{item.name}}</span>
              <span class="distance">距离您{{item.juli_txt}}</span>
            </div>
            <div>社区：{{item.village_name}}</div>
            <div class="address">取货地址：{{item.pick_addr}}</div>
          </div>
          <div class="icon iconfont arrow">&#xe603;</div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import MeScroll from 'mescroll.js'
export default {
  name: 'LeaderList',
  data () {
    return {
      list: [],
      nowAddress: '',
      leader_id: '',
      address: '',
      backNum: -2,
      backToIndex: false
    }
  },
  created () {
    // 获取定位信息
    this.leader_id = this.$util.storage.get('leader_id')
    this.address = this.$global.address
    if (this.address) {
      this.getLeaderList({ lng: this.address.lng, lat: this.address.lat })
      this.nowAddress = this.address.address_name
      if (this.address.address) {
        this.nowAddress += '(' + this.address.address + ')'
      }
    } else {
      if (this.$util.checkWeixin() && this.$util.checkAndroid()) {
        this.$util.getWxconfig(this.getLocation)
      } else {
        this.getLocation()
      }
    }
  },
  mounted () {
    this.mescroll = new MeScroll(this.$refs.leaderList, {
      down: {
        isLock: true
      }
    })
  },
  beforeRouteLeave (to, from, next) {
    console.log('222222228888', to, from)
    if (to.name == 'Leader' && this.backToIndex) {
      this.$router.go(-1)
    }
    next()
  },
  methods: {
    getLocation () {
      // 获取定位信息
      this.$util.getLocation(this.getLocationOk)
    },
    selectLeader (id) {
      this.$util.storage.set('leader_id', id)
      this.backToIndex = true
      this.$router.back()
    },
    // 定位成功的回调
    getLocationOk (res) {
      if (!res.errorMsg) {
        let param = { lng: res.lng, lat: res.lat }
        this.$util.getAdressDetail(res.lng, res.lat, this.getAddressBack)
        this.getLeaderList(param)
      } else {
        this.$messageBox.alert(res.errorMsg).then(action => {
          this.$router.push('/address')
        })
      }
    },
    getAddressBack (obj) {
      if (obj.status === 0) {
        this.nowAddress = obj.result.formatted_address + obj.result.sematic_description
      } else {
        this.nowAddress = this.$global.nowAddress
      }
    },
    async getLeaderList (param) {
      let res = await this.$api.getLeaderList(param)
      this.list = res
    }
  }
}
</script>

<style lang="stylus" scoped>
.leader-list
  .address-info
    height 100px
    color #fff
    background $color-main
    flexbox()
    justify-content center
    flex-direction column
    .desc
      padding 0 15px
    .now-address
      flexbox()
      justify-content space-between
      align-items center
      padding 10px 15px 0
      .address
        font-size 14px
        flex-grow 1
        ellipsis(2)
        font-size 14px
        padding-right 15px
        line-height 1.4
      .btn
        border 1PX solid #fff
        padding 8px 15px
        flex-shrink 0
        border-radius 15px
        color #fff
  .border-box
    background $color-main
    height 15px
    .border
      height 100%
      background #fff
      border-radius 15px 15px 0 0
  .list-info
    height calc(100% - 115px)
    background #fff
    .wrapper
      .item
        flexbox()
        align-items center
        padding 30px 0
        border-bottom 1PX solid #efefef
        margin 0 15px
        &:last-child
          border-bottom none
        .avatar
          align-self flex-start
          img
            width 40px
            height 40px
            border-radius 50%
        .info-box
          flex-grow 1
          padding 0 10px
          font-size 14px
          line-height 1.8
          .name
            flexbox()
            justify-content space-between
            .distance
              color #eb391f
              font-weight 500
          .address
            color #999999
            font-size 13px
        .arrow
          color #999
          padding-left 10px
</style>
